import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { requireEvidenceSources, requireHashCoverage, requireReviewIdentity, requireReportBinding } from './scripts/phase-evidence.mjs';
const modulePath = path.resolve('docs/phase-plans/complete-phase001.mjs');
const planPath = 'docs/phase-plans/Phase001.json';
const read = (file) => fs.readFileSync(file);
const json = (file) => JSON.parse(read(file));
const hash = (file) => createHash('sha256').update(read(file)).digest('hex');
const encode = (value) => JSON.stringify(value) + '\n';
const plan = json(planPath);
assert.equal(plan.attemptId, 'attempt-5');
const reviewPath = 'docs/evidence/attempts/Phase001/attempt-5/review.json';
const source = read(modulePath).toString('utf8').replace(/^import .*;\r?$/gm, '').replaceAll('import.meta.url', '__moduleUrl');
const execute = new Function('assert','fs','path','createHash','spawnSync','fileURLToPath','__moduleUrl','process','console','requireEvidenceSources','requireHashCoverage','requireReviewIdentity','requireReportBinding', source);
const observations = [];
function probe(name, files, withReview, expectedDiagnostic) {
  const overlay = new Map(Object.entries(files).map(([file, value]) => [path.resolve(file), Buffer.from(value)]));
  const output = [];
  const fakeProcess = { argv: ['node', modulePath, ...(withReview ? [] : ['--without-review'])], exitCode: 0 };
  const forbidden = () => { throw new Error('SIDE_EFFECT_FORBIDDEN'); };
  const proxyFs = { ...fs, readFileSync(file, ...args) { return overlay.get(path.resolve(file)) ?? fs.readFileSync(file, ...args); }, mkdirSync: forbidden, writeFileSync: forbidden };
  execute(assert, proxyFs, path, createHash, forbidden, fileURLToPath, pathToFileURL(modulePath).href, fakeProcess,
    { log(value) { output.push(JSON.parse(value)); }, error(value) { output.push(JSON.parse(value)); } },
    requireEvidenceSources, requireHashCoverage, requireReviewIdentity, requireReportBinding);
  assert.equal(fakeProcess.exitCode, expectedDiagnostic ? 1 : 0, name);
  const result = output.at(-1);
  if (expectedDiagnostic) assert(result.error.includes(expectedDiagnostic), name + ': ' + result.error);
  else assert.equal(result.status, 'PASS', name);
  observations.push({ name, inMemoryOnly: true, exitCode: fakeProcess.exitCode, reportedStatus: result.status, expectedDiagnostic: expectedDiagnostic ?? null,
    actualDiagnostic: result.error?.split('\n')[0] ?? null, independentReviewVerified: result.independentReviewVerified ?? null });
}
probe('unmodified-eleven-report-audit-control', {}, false);
const emptySources = {};
for (const item of plan.cases) emptySources[item.outputPath] = encode({ ...json(item.outputPath), sourceHashes: {} });
emptySources['docs/phase-plans/verify-phase001.mjs'] = read('docs/phase-plans/verify-phase001.mjs').toString('utf8') + '\n// IN_MEMORY_STALE_RUNNER_PROBE\n';
probe('old-attack-empty-source-maps-and-changed-runner', emptySources, false, 'REPORT_SOURCE_HASH');
const item = plan.cases[0];
const missing = json(item.outputPath);
delete missing.sourceHashes[plan.sourcePaths[0]];
probe('omitted-report-source-entry', { [item.outputPath]: encode(missing) }, false, 'REPORT_SOURCE_HASH');
probe('changed-runner-with-complete-source-maps', { 'docs/phase-plans/verify-phase001.mjs': emptySources['docs/phase-plans/verify-phase001.mjs'] }, false, 'REPORT_SOURCE_HASH');
const testReview = {
  phase: 1, attemptId: plan.attemptId, planPath, planHash: hash(planPath), decision: 'PASS',
  implementationContextId: plan.implementationContextId, contextId: 'IN_MEMORY_NEGATIVE_PROBE_CONTEXT',
  reviewerRunId: 'IN_MEMORY_NEGATIVE_PROBE_RUN', generatedBy: 'IN_MEMORY_NEGATIVE_PROBE_NOT_AN_ACCEPTANCE_REVIEW',
  runnerIdentity: { kind: 'INDEPENDENT_CODEX_AGENT', implementationAuthored: false }, issues: [], dispositions: [],
  sourceHashes: Object.fromEntries(plan.sourcePaths.map((file) => [file, hash(file)])),
  reportHashes: Object.fromEntries(plan.cases.map((test) => [test.outputPath, hash(test.outputPath)])),
};
for (const [name, diagnostic, mutate] of [
  ['old-attack-synthetic-review-and-empty-bindings', 'REVIEW_IDENTITY', (review) => { review.runnerIdentity.kind = 'SYNTHETIC_PROTOCOL_FIXTURE_NOT_AGENT_REVIEW'; review.contextId = plan.implementationContextId; review.sourceHashes = {}; review.reportHashes = {}; }],
  ['same-implementation-and-review-context', 'REVIEW_IDENTITY', (review) => { review.contextId = plan.implementationContextId; }],
  ['empty-review-source-map', 'REVIEW_FILE_HASH', (review) => { review.sourceHashes = {}; }],
  ['empty-review-report-map', 'REVIEW_FILE_HASH', (review) => { review.reportHashes = {}; }],
  ['omitted-review-report-entry', 'REVIEW_FILE_HASH', (review) => { delete review.reportHashes[plan.cases[0].outputPath]; }],
  ['missing-implementation-context-binding', 'REVIEW_IDENTITY', (review) => { delete review.implementationContextId; }],
]) {
  const review = structuredClone(testReview);
  mutate(review);
  probe(name, { [reviewPath]: encode(review) }, true, diagnostic);
}
const changedPlan = structuredClone(plan);
changedPlan.sourcePaths.pop();
probe('omitted-plan-source-entry', { [planPath]: encode(changedPlan) }, false, 'PLAN_SOURCE_PATHS');
console.log(JSON.stringify({ status: 'PASS', scope: 'IN_MEMORY_ADVERSARIAL_COMPLETE_AUDIT_RECHECK', runtime: process.version, sourceHash: hash(modulePath), helperHash: hash('scripts/phase-evidence.mjs'), filesystemWrites: 0, gitOperations: 0, observations }));
